// ============================================================================
// ШАГ 2. ПОДГОТОВКА ДАННЫХ — очистка, нормализация, объединение в один контекст
// ----------------------------------------------------------------------------
// На входе три разнородных источника:
//   1) Тарифы конкурентов  — CSV, собранный вручную с сайтов школ (первичный)
//   2) Отзывы пользователей — CSV с открытых площадок (поведенческий)
//   3) Обзор рынка          — текстовая выгрузка профильных материалов (вторичный)
//
// На выходе — один нормализованный JSON-контекст: единые названия школ, единая
// дата в формате YYYY-MM, единый список категорий, дедупликация и чистка текста.
// ============================================================================

const tariffsRaw = String($('1. Тарифы (текст)').first().json.data || '');
const reviewsRaw = String($('2. Отзывы (текст)').first().json.data || '');
const marketRaw  = String($('3. Обзор рынка (текст)').first().json.data || '');

// --- 1. Разбор CSV (с учётом кавычек и переводов строк внутри поля) ---
function parseCSV(text) {
  const rows = [];
  let row = [], field = '', inQ = false;
  const s = String(text).replace(/\r\n/g, '\n').replace(/\r/g, '\n');
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (inQ) {
      if (c === '"') {
        if (s[i + 1] === '"') { field += '"'; i++; } else { inQ = false; }
      } else field += c;
    } else if (c === '"') {
      inQ = true;
    } else if (c === ',') {
      row.push(field); field = '';
    } else if (c === '\n') {
      row.push(field); rows.push(row); row = []; field = '';
    } else {
      field += c;
    }
  }
  if (field.length || row.length) { row.push(field); rows.push(row); }
  const head = (rows.shift() || []).map(h => h.trim());
  return rows
    .filter(r => r.some(v => String(v).trim() !== ''))
    .map(r => {
      const o = {};
      head.forEach((h, i) => { o[h] = (r[i] === undefined ? '' : String(r[i])).trim(); });
      return o;
    });
}

// --- 2. Чистка текста: лишние пробелы, переводы строк, кавычки ---
function clean(v) {
  return String(v == null ? '' : v)
    .replace(/\s+/g, ' ')
    .replace(/^["'«»\s]+|["'«»\s]+$/g, '')
    .trim();
}

// --- 3. Единые названия школ (нормализация сущности) ---
const SCHOOLS = {
  'skyeng': 'Skyeng', 'скиенг': 'Skyeng', 'скайенг': 'Skyeng', 'скай инглиш': 'Skyeng',
  'инглекс': 'Инглекс', 'englex': 'Инглекс',
  'englishdom': 'EnglishDom', 'инглишдом': 'EnglishDom', 'инглиш дом': 'EnglishDom'
};
function normSchool(v) {
  const k = clean(v).toLowerCase().replace(/[()«»"]/g, '').replace(/\s+/g, ' ');
  if (SCHOOLS[k]) return SCHOOLS[k];
  const hit = Object.keys(SCHOOLS).find(a => k.includes(a));
  return hit ? SCHOOLS[hit] : clean(v);
}

// --- 4. Единый формат даты: DD.MM.YYYY | YYYY-MM-DD | «март 2025» -> YYYY-MM ---
const MONTHS = {
  'январ': '01', 'феврал': '02', 'март': '03', 'апрел': '04', 'ма': '05',
  'июн': '06', 'июл': '07', 'август': '08', 'сентябр': '09', 'октябр': '10',
  'ноябр': '11', 'декабр': '12'
};
function normDate(v) {
  const s = clean(v);
  let m = s.match(/(\d{4})-(\d{2})-(\d{2})/);                 // 2025-03-12
  if (m) return m[1] + '-' + m[2];
  m = s.match(/(\d{1,2})[.\/](\d{1,2})[.\/](\d{4})/);          // 12.03.2025
  if (m) return m[3] + '-' + m[2].padStart(2, '0');
  m = s.match(/(\d{1,2})\s+([а-яё]+)\s+(\d{4})/i);             // 12 марта 2025
  if (m) {
    const key = Object.keys(MONTHS).find(k => m[2].toLowerCase().startsWith(k));
    if (key) return m[3] + '-' + MONTHS[key];
  }
  m = s.match(/([а-яё]+)\s+(\d{4})/i);                         // март 2025
  if (m) {
    const key = Object.keys(MONTHS).find(k => m[1].toLowerCase().startsWith(k));
    if (key) return m[2] + '-' + MONTHS[key];
  }
  m = s.match(/(\d{4})/);                                      // только год
  if (m) return m[1];
  return 'дата не указана';
}

// --- 5. Единый список категорий: любой текст -> одна каноническая категория ---
// Сначала пытаемся распознать ЯВНО указанную категорию (колонка category),
// и только если её нет — определяем категорию по тексту отзыва. Так текстовые
// совпадения не перебивают разметку, сделанную при сборе данных.
const CATEGORY_ALIASES = [
  [/списан|возврат|деньг|refund|двойн|удерж/i,                              'Списания и возвраты'],
  [/навязыв|навяза|впарив|доплат|продаж/i,                                  'Навязывание услуг'],
  [/пробн|бесплатн|вводн/i,                                                 'Пробный урок'],
  [/разговорн|клуб|speaking/i,                                              'Разговорный клуб'],
  [/гибк|удобн|свободн|круглосуточн|расписание под/i,                       'Гибкость расписания'],
  [/отмен|перенос|расписан|график|опозда/i,                                 'Отмена и перенос занятий'],
  [/цен|дорог|стоимост|тариф|оплат|подорож/i,                               'Цена и оплата'],
  [/препод|учител|репетитор|носител|педагог/i,                              'Преподаватель'],
  [/техн|платформ|приложен|интерфейс|кабинет|связ|звук|лаг|глюч|микрофон/i, 'Платформа и техника'],
  [/поддержк|менеджер|куратор|служб/i,                                      'Поддержка'],
  [/результат|прогресс|уровен|выучил|эффект|заговор/i,                      'Результат и прогресс'],
  [/домашн|материал|учебник|методик/i,                                      'Материалы и ДЗ'],
  [/сайт|регистрац/i,                                                       'Сайт и личный кабинет'],
  [/репутац|политич|контор|скандал|довери/i,                                'Репутация компании']
];
// те же правила, но применяются к тексту отзыва, если категория не указана
const CATEGORY_RULES = [
  [/списан|двойн.*оплат|верн.*деньг|возврат|refund/i,                      'Списания и возвраты'],
  [/навязыв|навяза|доплат|прода.*(курс|пакет)|впарив/i,                     'Навязывание услуг'],
  [/пробн|бесплатн.*урок|вводн.*урок/i,                                     'Пробный урок'],
  [/разговорн.*(клуб|практик)|клуб/i,                                       'Разговорный клуб'],
  [/гибк|удобн.*врем|свободн.*слот|круглосуточн/i,                          'Гибкость расписания'],
  [/отмен|перенос|расписан|график|опозда/i,                                 'Отмена и перенос занятий'],
  [/цен|дорог|стоимост|тариф|оплат|подорож|дороже/i,                        'Цена и оплата'],
  [/препод|учител|репетитор|носител|педагог/i,                              'Преподаватель'],
  [/техн|платформ|приложен|интерфейс|связь|звук|лага|глюч|микрофон|кабинет/i, 'Платформа и техника'],
  [/поддержк|менеджер|служб.*забот|куратор/i,                               'Поддержка'],
  [/результат|прогресс|заговор|уровен|выучил|стал.*говорить|эффект/i,       'Результат и прогресс'],
  [/домашн|материал|учебник|методик/i,                                      'Материалы и ДЗ'],
  [/регистрац|личн.*кабинет|сайт/i,                                         'Сайт и личный кабинет'],
  [/репутац|политич|скандал|контор|довери/i,                                'Репутация компании']
];
function normCategory(explicit, text) {
  const e = clean(explicit).toLowerCase();
  if (e) {
    for (const [re, name] of CATEGORY_ALIASES) if (re.test(e)) return name;
  }
  const t = clean(text);
  for (const [re, name] of CATEGORY_RULES) if (re.test(t)) return name;
  return 'Прочее';
}

// --- 6. Тональность: из оценки (1-5) либо из текста ---
function normType(type, rating, text) {
  const t = clean(type).toLowerCase();
  if (/позитив|positive/.test(t)) return 'позитив';
  if (/негатив|negative/.test(t)) return 'негатив';
  if (/смешан|mixed|нейтрал/.test(t)) return 'смешанный';
  const r = parseFloat(clean(rating).replace(',', '.'));
  if (!isNaN(r)) return r >= 4 ? 'позитив' : (r <= 2 ? 'негатив' : 'смешанный');
  if (/отличн|нрав|рекоменд|довол|супер|удобн/i.test(text)) return 'позитив';
  if (/ужас|разочаров|плохо|обман|вернул|больше не/i.test(text)) return 'негатив';
  return 'смешанный';
}

// --- 7. Нормализация трёх источников ---
const tariffs = parseCSV(tariffsRaw)
  .map(r => {
    const priceFrom = parseFloat(clean(r.price_from).replace(/[^\d.]/g, '')) || null;
    const priceTo   = parseFloat(clean(r.price_to).replace(/[^\d.]/g, '')) || null;
    const perLesson = parseFloat(clean(r.price_per_lesson).replace(/[^\d.]/g, '')) || null;
    return {
      source: 'Тарифы конкурентов',
      school: normSchool(r.school),
      plan: clean(r.plan),
      lessons: clean(r.lessons),
      lesson_minutes: clean(r.lesson_minutes),
      price_per_lesson: perLesson,
      price_from: priceFrom,
      price_to: priceTo,
      // Валюта обязательна: EnglishDom работает на украинском рынке и публикует
      // цены в гривнах. Без пометки валюты модель сравнила бы 380 грн с 1890 ₽
      // как сопоставимые числа.
      currency: /uah|грн/i.test(clean(r.currency)) ? 'грн' : '₽',
      format: clean(r.format),
      trial_lesson: clean(r.trial_lesson),
      notes: clean(r.notes),
      source_url: clean(r.source_url),
      checked_date: normDate(r.checked_date)
    };
  })
  .filter(r => r.school && (r.plan || r.price_from));

const seenReview = new Set();
const reviews = parseCSV(reviewsRaw)
  .map(r => {
    const text = clean(r.text);
    return {
      source: 'Отзывы пользователей',
      id: clean(r.id),
      school: normSchool(r.school),
      date: normDate(r.date),
      rating: clean(r.rating),
      platform: clean(r.platform),
      type: normType(r.type, r.rating, text),
      category: normCategory(r.category, text),
      text: text.length > 600 ? text.slice(0, 600) + '…' : text,
      source_url: clean(r.source_url)
    };
  })
  .filter(r => {
    if (!r.school || r.text.length < 15) return false;
    const key = (r.school + '|' + r.text.slice(0, 80)).toLowerCase();
    if (seenReview.has(key)) return false;   // дедупликация повторов
    seenReview.add(key);
    return true;
  });

const marketReview = String(marketRaw).split('\n').map(l => l.replace(/\s+$/, '')).join('\n').trim();

// --- 8. Первичная статистика: частоты по категориям (основа для группировки) ---
const byCategory = {};
for (const r of reviews) {
  const c = byCategory[r.category] || (byCategory[r.category] = {
    category: r.category, total: 0, негатив: 0, позитив: 0, смешанный: 0,
    schools: {}, platforms: {}, months: {}, examples: []
  });
  c.total++;
  c[r.type] = (c[r.type] || 0) + 1;
  c.schools[r.school] = (c.schools[r.school] || 0) + 1;
  c.platforms[r.platform] = (c.platforms[r.platform] || 0) + 1;
  if (/^\d{4}-\d{2}$/.test(r.date)) c.months[r.date] = (c.months[r.date] || 0) + 1;
  if (c.examples.length < 3) c.examples.push('#' + r.id + ': ' + r.text.slice(0, 160));
}

const context = {
  prepared_at: new Date().toISOString().slice(0, 10),
  object: 'Ниша онлайн-школ английского языка (обучение взрослых, B2C, Россия)',
  competitors: ['Skyeng', 'Инглекс', 'EnglishDom'],
  sources: {
    tariffs: { type: 'первичный', role: 'основной', items: tariffs.length, file: 'tariffs.csv' },
    reviews: { type: 'поведенческий', role: 'основной', items: reviews.length, file: 'reviews.csv' },
    market:  { type: 'вторичный', role: 'дополнительный', file: 'market-review.md' }
  },
  normalized: { tariffs: tariffs, reviews: reviews, market_review_text: marketReview },
  stats: {
    reviews_total: reviews.length,
    by_school: reviews.reduce((a, r) => (a[r.school] = (a[r.school] || 0) + 1, a), {}),
    by_type: reviews.reduce((a, r) => (a[r.type] = (a[r.type] || 0) + 1, a), {}),
    platforms: reviews.reduce((a, r) => (a[r.platform] = (a[r.platform] || 0) + 1, a), {}),
    by_month: reviews.filter(r => /^\d{4}-\d{2}$/.test(r.date))
      .reduce((a, r) => (a[r.date] = (a[r.date] || 0) + 1, a), {}),
    date_range: (() => {
      const d = reviews.map(r => r.date).filter(x => /^\d{4}-\d{2}/.test(x)).sort();
      return d.length ? d[0] + ' … ' + d[d.length - 1] : 'даты не указаны';
    })(),
    by_category: Object.values(byCategory).sort((a, b) => b.total - a.total)
  }
};

return [{ json: { context: context, context_json: JSON.stringify(context) } }];

// ============================================================================
// ШАГ 3. ФИЛЬТРАЦИЯ ШУМА, ГРУППИРОВКА И ВЫДЕЛЕНИЕ КЛЮЧЕВЫХ СИГНАЛОВ
// ----------------------------------------------------------------------------
// Здесь заложены жёсткие правила, которые не дают агенту выдать случайный
// сигнал за вывод. Правила видны прямо в коде — это «правила workflow».
//
//   Правило 1 (порог значимости). Сигнал попадает в выводы, только если он
//     подтверждён >= MIN_SIGNAL независимыми единицами наблюдения.
//   Правило 2 (кросс-подтверждение). Сигнал усиливается, если встречается
//     более чем у одной школы ИЛИ подтверждается другим источником (обзор рынка).
//   Правило 3 (уровни аналитики). Каждый сигнал получает уровень:
//     ДАННЫЕ      — единичный факт (в выводы не идёт, остаётся в приложении);
//     НАБЛЮДЕНИЕ  — повторяется, но без объяснения значимости;
//     ИНСАЙТ      — повторяется + есть подтверждение + понятно, что с этим делать;
//     ГИПОТЕЗА    — единичный/слабый сигнал, который нельзя терять, но нельзя
//                   и подавать как вывод.
// ============================================================================

const ctx = $json.context;
const reviews = ctx.normalized.reviews || [];
const tariffs = ctx.normalized.tariffs || [];
const marketText = String(ctx.normalized.market_review_text || '');

const MIN_SIGNAL = 2;        // минимум единиц наблюдения для «наблюдения»
const MIN_INSIGHT = 3;       // минимум единиц наблюдения для «инсайта»

const uniq = a => Array.from(new Set(a));

// --- 1. Группировка: похожие сигналы объединяются в одну категорию ---
const groups = {};
for (const r of reviews) {
  const g = groups[r.category] || (groups[r.category] = {
    category: r.category, items: [], schools: [], platforms: [], months: [],
    types: { 'позитив': 0, 'негатив': 0, 'смешанный': 0 }
  });
  g.items.push(r);
  g.schools = uniq(g.schools.concat([r.school]));
  g.platforms = uniq(g.platforms.concat([r.platform]));
  if (/^\d{4}-\d{2}$/.test(r.date)) g.months = uniq(g.months.concat([r.date]));
  g.types[r.type]++;
}

// --- 2. Кросс-подтверждение из вторичного источника ---
// Ключевые слова категории, наличие которых в обзоре рынка усиливает сигнал.
const MARKET_KEYWORDS = {
  'Цена и оплата':                 [/цен|подорож|стоимост|чек/i],
  'Списания и возвраты':           [/возврат|списан|refund|оплат/i],
  'Преподаватель':                 [/преподавател|репетитор|кадр|текучк/i],
  'Платформа и техника':           [/платформ|приложен|мобильн|онлайн-урок|технолог/i],
  'Поддержка':                     [/поддержк|сервис|клиентск/i],
  'Результат и прогресс':          [/результат|эффективн|прогресс|качеств/i],
  'Отмена и перенос занятий':      [/расписан|гибк|отмен/i],
  'Навязывание услуг':             [/навязыв|дополнительн.*продаж|upsell|апсел/i],
  'Пробный урок':                  [/пробн|бесплатн|вводн/i],
  'Гибкость расписания':           [/гибк|расписан|24\/7|круглосуточн/i],
  'Разговорный клуб':              [/разговорн|speaking|клуб|практик/i],
  'Материалы и ДЗ':                [/материал|методик|учебн|контент/i],
  'Сайт и личный кабинет':         [/интерфейс|личн.*кабинет|сайт|регистрац/i],
  'Репутация компании':            [/репутац|довери|бренд|скандал/i],
  'Прочее':                        []
};
const categoryInMarket = c =>
  (MARKET_KEYWORDS[c] || []).some(re => re.test(marketText));

// --- 3. Присвоение уровней аналитики ---
const observations = [];
const noise = [];
const hypotheses = [];

for (const g of Object.values(groups).sort((a, b) => b.items.length - a.items.length)) {
  const count = g.items.length;
  const crossSchool = g.schools.length >= 2;
  const crossSource = categoryInMarket(g.category);
  const negative = g.types['негатив'] || 0;
  const positive = g.types['позитив'] || 0;
  const dominant = negative > positive ? 'негатив'
                 : positive > negative ? 'позитив' : 'смешанный';

  const signal = {
    category: g.category,
    count: count,
    schools: g.schools,
    platforms: g.platforms,
    months: g.months,
    types: g.types,
    dominant_sentiment: dominant,
    cross_school: crossSchool,
    cross_source: crossSource,
    examples: g.items.slice(0, 4).map(r => '#' + r.id + ' (' + r.school + ', ' + r.date + '): ' + r.text.slice(0, 200)),
    schools_negative: uniq(g.items.filter(r => r.type === 'негатив').map(r => r.school))
  };

  if (count >= MIN_INSIGHT && (crossSchool || crossSource)) {
    // Правило 2+3: повторяется, подтверждается, понятно что делать — ИНСАЙТ
    signal.level = 'ИНСАЙТ (подтверждён: ' + count + ' наблюдений, школ: ' + g.schools.length +
                   (crossSource ? ', + подтверждение из обзора рынка' : '') + ')';
    observations.push(signal);
  } else if (count >= MIN_SIGNAL) {
    // Правило 1: повторяется в нескольких единицах наблюдения — НАБЛЮДЕНИЕ
    signal.level = 'НАБЛЮДЕНИЕ (повторяется: ' + count + ' упоминаний' +
                   (crossSchool ? ', у ' + g.schools.length + ' школ' : '') + ')';
    observations.push(signal);
  } else if (negative >= 1 || crossSource) {
    // Единичное упоминание: выводом быть не может, но и терять его нельзя — ГИПОТЕЗА.
    // Отдельно помечаем случай, когда сигнал всё-таки подтверждён вторым источником.
    signal.level = 'ГИПОТЕЗА (единичное упоминание' +
                   (crossSource ? ', но подтверждено обзором рынка' : ', подтверждений недостаточно') + ')';
    hypotheses.push(signal);
  } else {
    // Единичный нейтральный или позитивный сигнал — ДАННЫЕ, в выводы не идёт
    signal.level = 'ДАННЫЕ (единичный факт, исключён из выводов)';
    noise.push(signal);
  }
}

// --- 4. Уязвимости конкурентов: только повторяющиеся (>=2) негативные сигналы ---
const weaknesses = [];
for (const school of ctx.competitors) {
  const bad = reviews.filter(r => r.school === school && r.type === 'негатив');
  const byCat = {};
  for (const r of bad) byCat[r.category] = (byCat[r.category] || 0) + 1;
  const confirmed = Object.entries(byCat).filter(([, n]) => n >= MIN_SIGNAL)
    .sort((a, b) => b[1] - a[1]);
  if (confirmed.length) {
    weaknesses.push({
      school: school,
      negative_total: bad.length,
      negative_share: reviews.filter(r => r.school === school).length
        ? Math.round(bad.length / reviews.filter(r => r.school === school).length * 100) : 0,
      confirmed: confirmed.map(([c, n]) => ({ category: c, mentions: n })),
      single_mentions: Object.entries(byCat).filter(([, n]) => n < MIN_SIGNAL).map(([c]) => c),
      examples: bad.filter(r => confirmed.some(([c]) => c === r.category))
        .slice(0, 4).map(r => '#' + r.id + ' (' + r.category + '): ' + r.text.slice(0, 180))
    });
  }
}

// --- 5. Сводка по тарифам (первичный источник) ---
const tariffSummary = ctx.competitors.map(school => {
  const rows = tariffs.filter(t => t.school === school);
  const prices = rows.map(r => r.price_per_lesson).filter(Boolean);
  const froms = rows.map(r => r.price_from).filter(Boolean);
  const tos = rows.map(r => r.price_to).filter(Boolean);
  return {
    school: school,
    plans: rows.length,
    // Минимум и максимум считаются ВНУТРИ одной школы, поэтому смешения валют
    // не происходит: у каждой школы своя валюта (Россия — рубли, EnglishDom — гривны).
    currency: uniq(rows.map(r => r.currency).filter(Boolean)).join('/') || '₽',
    price_per_lesson_min: prices.length ? Math.min(...prices) : null,
    price_per_lesson_max: prices.length ? Math.max(...prices) : null,
    price_from_min: froms.length ? Math.min(...froms) : null,
    price_to_max: tos.length ? Math.max(...tos) : null,
    lesson_minutes: uniq(rows.map(r => r.lesson_minutes).filter(Boolean)),
    formats: uniq(rows.map(r => r.format).filter(Boolean)),
    trial: uniq(rows.map(r => r.trial_lesson).filter(Boolean)),
    notes: uniq(rows.map(r => r.notes).filter(Boolean)).slice(0, 6),
    urls: uniq(rows.map(r => r.source_url).filter(Boolean))
  };
});

// --- 6. Упаковка для LLM: только то, что прошло фильтр ---
function tbl(rows) {
  return rows.map(r => '| ' + r.join(' | ') + ' |').join('\n');
}

const monthly = Object.entries(ctx.stats.by_month).sort();

let pack = '# ПОДГОТОВЛЕННЫЙ КОНТЕКСТ ДЛЯ АНАЛИЗА\n\n';
pack += '## Контекст\n';
pack += '- Объект анализа: ' + ctx.object + '\n';
pack += '- Конкуренты: ' + ctx.competitors.join(', ') + '\n';
pack += '- Период данных: ' + ctx.stats.date_range + '\n';
pack += '- Дата подготовки: ' + ctx.prepared_at + '\n';
pack += '- Источники: ' + Object.entries(ctx.sources)
  .map(([k, v]) => v.type + ' (' + v.role + ') — ' + (v.file || k) +
       (v.items ? ', единиц: ' + v.items : '')).join('; ') + '\n\n';

pack += '## Тарифы конкурентов (первичный источник, нормализовано)\n';
pack += '| Школа | Тариф | Занятий | Цена занятия | Валюта | Мин | Макс | Длит., мин | Формат | Пробный | Примечание |\n';
pack += '|---|---|---|---|---|---|---|---|---|---|---|\n';
pack += tbl(tariffs.map(t => [t.school, t.plan, t.lessons,
  t.price_per_lesson || '—', t.currency || '₽', t.price_from || '—', t.price_to || '—',
  t.lesson_minutes || '—', t.format || '—', t.trial_lesson || '—', (t.notes || '').slice(0, 160)])) + '\n\n';

// Предупреждение обязательно: иначе модель складывает гривны с рублями.
const currencies = uniq(tariffs.map(t => t.currency));
if (currencies.length > 1) {
  pack += 'ВНИМАНИЕ К ТАБЛИЦЕ ТАРИФОВ: цены приведены в РАЗНЫХ валютах (колонка «Валюта»). ' +
    'Тарифы EnglishDom — в гривнах (грн), потому что школа работает на украинском рынке; ' +
    'рублёвых тарифов у неё нет. Численно сравнивать гривны с рублями НЕЛЬЗЯ, ' +
    'суммы и средние по разным валютам не считай.\n\n';
}

pack += '## Сводка по тарифам\n';
pack += '| Школа | Тарифов | Валюта | Мин за занятие | Макс за занятие | Длительность | Форматы | Пробный урок |\n|---|---|---|---|---|---|---|---|\n';
pack += tbl(tariffSummary.map(s => [s.school, s.plans, s.currency,
  s.price_per_lesson_min || '—', s.price_per_lesson_max || '—',
  s.lesson_minutes.join('/') || '—', s.formats.join('; ') || '—', s.trial.join('; ') || '—'])) + '\n\n';

pack += '## Отзывы пользователей: частоты (поведенческий источник)\n';
pack += 'Всего отзывов: ' + ctx.stats.reviews_total + '. По школам: ' +
  Object.entries(ctx.stats.by_school).map(([k, v]) => k + ' — ' + v).join(', ') + '.\n';
pack += 'Тональность: ' + Object.entries(ctx.stats.by_type).map(([k, v]) => k + ' — ' + v).join(', ') + '.\n';
pack += 'Площадки: ' + Object.entries(ctx.stats.platforms).map(([k, v]) => k + ' — ' + v).join(', ') + '.\n';
if (monthly.length) pack += 'По месяцам: ' + monthly.map(([m, n]) => m + ' — ' + n).join(', ') + '.\n';
pack += '\n### Повторяющиеся сигналы (прошли фильтр шума, порог >= ' + MIN_SIGNAL + ')\n';
for (const s of observations) {
  pack += '\n**' + s.category + '** — ' + s.level + '\n';
  pack += '  школ: ' + s.schools.join(', ') + '; тональность: ' + s.dominant_sentiment +
          ' (негатив ' + s.types['негатив'] + ', позитив ' + s.types['позитив'] + ', смешанный ' + s.types['смешанный'] + ')\n';
  if (s.months.length) pack += '  месяцы: ' + s.months.join(', ') + '\n';
  for (const e of s.examples) pack += '  - ' + e + '\n';
}
pack += '\n### Сигналы ниже порога (переданы как ГИПОТЕЗЫ, не как выводы)\n';
if (!hypotheses.length) pack += '- нет\n';
for (const h of hypotheses) {
  pack += '- ' + h.category + ' — упоминаний: ' + h.count + ' (школы: ' + h.schools.join(', ') + ')\n';
}
pack += '\n### Единичные факты (ШУМ, в выводы НЕ включать)\n';
if (!noise.length) pack += '- нет\n';
for (const n of noise) {
  pack += '- ' + n.category + ' — 1 упоминание (' + n.schools.join(', ') + ')\n';
}

pack += '\n## Уязвимости конкурентов (повторяющиеся негативные сигналы, >= ' + MIN_SIGNAL + ')\n';
for (const w of weaknesses) {
  pack += '\n**' + w.school + '** — негативных отзывов ' + w.negative_total + ' из ' +
          reviews.filter(r => r.school === w.school).length + ' (' + w.negative_share + '%)\n';
  for (const c of w.confirmed) pack += '  - ' + c.category + ' — подтверждено ' + c.mentions + ' отзывами\n';
  if (w.single_mentions.length) pack += '  - единичные жалобы (не выводы): ' + w.single_mentions.join(', ') + '\n';
  for (const e of w.examples) pack += '  - пример: ' + e + '\n';
}

pack += '\n## Отраслевой обзор рынка (вторичный источник, полный текст)\n';
pack += marketText + '\n';

return [{
  json: {
    context: ctx,
    analytics_pack: pack,
    counts: {
      reviews: reviews.length, tariffs: tariffs.length,
      observations: observations.length, hypotheses: hypotheses.length,
      noise_excluded: noise.length, weaknesses: weaknesses.length
    },
    observations: observations, hypotheses: hypotheses, noise: noise,
    weaknesses: weaknesses, tariff_summary: tariffSummary
  }
}];

// ============================================================================
// ШАГ 5. ОЧИСТКА ОТВЕТА LLM И ФОРМИРОВАНИЕ ИТОГОВОГО БРИФИНГА
// ----------------------------------------------------------------------------
// Используемая модель (deepseek-v4.1-flash:cloud) — «рассуждающая»: вместе с
// брифингом она возвращает цепочку размышлений на английском, причём в самих
// рассуждениях часто повторяется план с теми же заголовками разделов.
// Поэтому надёжный признак готового брифинга — не маркер, а ПОЛНЫЙ набор из
// шести разделов, идущих по порядку. Берём самый поздний такой фрагмент:
// рассуждения всегда идут раньше финального ответа.
// ============================================================================

const src = $input.first().json;
const raw = String(
  (src.message && src.message.content) ? src.message.content :
  (src.content || src.text || src.output || '')
).replace(/\r\n/g, '\n');

// Ключевые слова обязательных разделов — в том порядке, в котором они должны идти.
const SEC_KEYWORDS = [/контекст/i, /тренд/i, /паттерн/i, /уязвим/i, /гипотез/i, /что делать/i];

// Ищем заголовки разделов ПО ВСЕМУ тексту, а не по началам строк: модель иногда
// приклеивает заголовок к служебной фразе и он оказывается не в начале строки —
// например «I'll write concisely but completely.### 1. Контекст анализа».
// Такой заголовок старый экстрактор не видел и возвращал вместо брифинга план.
function findHeads(t) {
  const re = /(#{1,6})[ \t]*([1-6])\.[ \t]*([^\n]*)/g;
  const heads = [];
  let m;
  while ((m = re.exec(t)) !== null) {
    const sec = parseInt(m[2], 10) - 1;
    if (sec < 0 || sec > 5) continue;
    if (!SEC_KEYWORDS[sec].test(m[3])) continue;   // «1. Что-то другое» не считаем
    heads.push({ sec: sec, start: m.index });
  }
  return heads;
}

// Тело раздела-заглушки: «...», «перечислить.», «list.», «3-5 действий.» —
// так модель размечает план перед тем, как писать сам брифинг.
function looksLikeStub(s) {
  return s.replace(/[.\-—–…\s]/g, '').length < 30;
}

// --- 1. Отрезаем служебные рассуждения модели ---
function extractBriefing(t) {
  const lines = t.split('\n');
  const heads = findHeads(t);

  // Основной способ: последний фрагмент, где все шесть разделов идут по порядку,
  // и при этом каждый раздел наполнен текстом, а не заглушкой.
  const starts = heads.filter(h => h.sec === 0);
  for (let k = starts.length - 1; k >= 0; k--) {
    const chain = [starts[k]];
    let ok = true;
    for (let s = 1; s < 6; s++) {
      const next = heads.find(h => h.sec === s && h.start > chain[chain.length - 1].start);
      if (!next) { ok = false; break; }
      chain.push(next);
    }
    if (!ok) continue;

    // Проверяем, что все шесть разделов действительно написаны.
    let stubbed = false;
    for (let i = 0; i < 6; i++) {
      const bodyStart = t.indexOf('\n', chain[i].start);
      const from = bodyStart < 0 ? t.length : bodyStart + 1;
      const to = i < 5 ? chain[i + 1].start : t.length;
      if (looksLikeStub(t.slice(from, to))) { stubbed = true; break; }
    }
    if (stubbed) continue;

    // Модель нередко печатает ответ дважды. Конец брифинга — начало ПОВТОРНОГО
    // раздела 1, то есть следующий заголовок первого раздела после шестого.
    const restart = heads.find(h => h.sec === 0 && h.start > chain[5].start);
    const end = restart ? restart.start : t.length;

    const body = t.slice(chain[0].start, end).trim();
    if (body.length >= 800) return body;
  }

  // Запасной способ 1: всё после последнего маркера «###».
  const marker = t.lastIndexOf('###');
  if (marker >= 0) return t.slice(marker).replace(/^#+\s*/, '').trim();

  // Запасной способ 2: первый заголовок Markdown с кириллицей.
  let head = -1;
  for (let i = 0; i < lines.length; i++) {
    if (/^#{1,3}\s+\S/.test(lines[i]) && /[а-яё]/i.test(lines[i])) { head = i; break; }
  }
  if (head >= 0) return lines.slice(head).join('\n').trim();

  // Запасной способ 3: отбрасываем ведущие англоязычные абзацы.
  const out = [];
  let started = false;
  for (const l of lines) {
    const latin = (l.match(/[A-Za-z]/g) || []).length;
    const cyr = (l.match(/[А-Яа-яЁё]/g) || []).length;
    if (!started && latin > 20 && cyr < 5) continue;
    if (l.trim()) started = true;
    out.push(l);
  }
  return out.join('\n').trim();
}

let briefing = extractBriefing(raw);

// --- 2. Финальная чистка: маркеры списка-заглушек и хвостовые служебные строки ---
briefing = briefing
  .replace(/\n{3,}/g, '\n\n')
  .replace(/^\s*(###\s*)?(Вот|Here is|Below is)[^\n]*\n/i, '')
  .trim();

// --- 3. Подставляем фактические метаданные прогона ---
const counts = $('Фильтрация и группировка').first().json.counts;
const ctxStats = $('Фильтрация и группировка').first().json.context.stats;

const header =
  '# Аналитический брифинг: онлайн-школы английского языка\n\n' +
  '_Сформирован ИИ-агентом рыночной аналитики. ' +
  'Дата прогона: ' + $now.setZone('Europe/Moscow').toFormat('yyyy-MM-dd HH:mm') + ' (МСК)._\n\n' +
  '_Объект анализа: ' + $('Фильтрация и группировка').first().json.context.object + '._\n' +
  '_Конкуренты: ' + $('Фильтрация и группировка').first().json.context.competitors.join(', ') + '._\n' +
  '_Период данных: ' + ctxStats.date_range + '._\n' +
  '_Обработано: тарифных позиций — ' + counts.tariffs + ', отзывов — ' + counts.reviews + '._\n' +
  '_Прошло фильтр шума: сигналов-наблюдений — ' + counts.observations +
  ', гипотез — ' + counts.hypotheses + ', исключено единичных — ' + counts.noise_excluded + '._\n\n---\n\n';

const briefingMd = header + briefing;

if (!briefing || briefing.length < 300) {
  throw new Error('Брифинг пуст или слишком короткий (' + (briefing || '').length +
                  ' символов). Проверьте ответ LLM.');
}

// Предохранитель: если в извлечённом тексте нет всех шести разделов, значит
// за брифинг принят план или черновик. Лучше упасть с внятной ошибкой, чем
// отдать команде заглушку с «...» вместо анализа.
const foundSecs = findHeads(briefing).map(h => h.sec);
const lackSecs = [0, 1, 2, 3, 4, 5].filter(n => foundSecs.indexOf(n) < 0);
if (lackSecs.length) {
  throw new Error('В извлечённом брифинге нет разделов: ' +
    lackSecs.map(n => n + 1).join(', ') +
    '. Похоже, за брифинг принят план или черновик ответа модели.');
}

return [{
  json: {
    briefing_md: briefingMd,
    briefing_chars: briefingMd.length,
    generated_at: $now.setZone('Europe/Moscow').toFormat('yyyy-MM-dd HH:mm'),
    run_date: $now.setZone('Europe/Moscow').toFormat('yyyy-MM-dd'),
    counts: counts,
    raw_llm_chars: raw.length,
    reasoning_stripped: raw.length - briefing.length
  }
}];

// ============================================================================
// ШАГ 6. АВТОМАТИЧЕСКАЯ САМОПРОВЕРКА КАЧЕСТВА БРИФИНГА
// ----------------------------------------------------------------------------
// Задание требует, чтобы результат можно было проверить. Этот узел прогоняет
// брифинг по чек-листу механически, а не «на глаз»:
//   1) все ли обязательные разделы на месте;
//   2) у каждого вывода есть строка «Основание:»;
//   3) упомянуты ли конкуренты;
//   4) нет ли ЧИСЕЛ, которых не было в исходных данных (защита от галлюцинаций);
//   5) не попали ли в выводы сигналы, которые фильтр пометил как шум;
//   6) отделены ли гипотезы от подтверждённых выводов.
// ============================================================================

const brief = $('Очистка брифинга').first().json;
const pack = $('Фильтрация и группировка').first().json;
const md = String(brief.briefing_md || '');
const source = String(pack.analytics_pack || '');

const checks = [];
const add = (name, ok, detail) => checks.push({ name: name, ok: !!ok, detail: detail });

// --- 1. Обязательные разделы ---
const REQUIRED = [
  ['1. Контекст анализа', /##\s*1\.\s*Контекст/i],
  ['2. Тренды',          /##\s*2\.\s*Тренды/i],
  ['3. Паттерны',        /##\s*3\.\s*Паттерны/i],
  ['4. Уязвимости конкурентов', /##\s*4\.\s*Уязвимост/i],
  ['5. Гипотезы и ограничения', /##\s*5\.\s*Гипотез/i],
  ['6. Что делать',      /##\s*6\.\s*Что делать/i]
];
const missing = REQUIRED.filter(([, re]) => !re.test(md)).map(([n]) => n);
add('Все обязательные разделы присутствуют', missing.length === 0,
    missing.length ? 'нет разделов: ' + missing.join(', ') : 'найдены все ' + REQUIRED.length + ' разделов');

// --- 2. Строки «Основание:» ---
// ВАЖНО: \w в JavaScript не включает кириллицу, поэтому «Основание:» нужно
// ловить явным классом [а-яё], иначе счётчик всегда даёт ноль.
const grounds = (md.match(/Основан[а-яё]*\s*[:—–]/gi) || []).length;
// примерно считаем выводы: пункты списка и подзаголовки в разделах 2-4
const sec24 = (md.split(/##\s*5\./)[0].split(/##\s*2\./)[1]) || '';
// выводы в брифинге оформляются и списком, и подзаголовками, и жирным лидом
const claims = (sec24.match(/^\s*(?:[-*]|\d+\.)\s+\S|^#{3,4}\s+\S|^\*\*[^*\n]+\*\*/gm) || []).length;
add('У выводов указаны основания', grounds >= 3,
    'строк «Основание:» — ' + grounds + ', пунктов-выводов в разделах 2–4 — ~' + claims);

// --- 3. Конкуренты упомянуты ---
const comps = pack.context.competitors || [];
const mentioned = comps.filter(c => new RegExp(c.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i').test(md));
const absent = comps.filter(c => mentioned.indexOf(c) < 0);
add('Упомянуты все конкуренты', absent.length === 0,
    absent.length ? 'в брифинге нет: ' + absent.join(', ')
                  : 'найдены все ' + comps.length + ': ' + comps.join(', '));

// --- 4. Числа, которых нет в исходных данных (проверка на галлюцинации) ---
function numbers(text) {
  const out = new Set();
  // Пробел — разделитель разрядов ТОЛЬКО если за ним ровно три цифры и дальше
  // не цифра. Иначе «#9 2025-10» склеивалось бы в 92025, «#23 2026-08» — в 232026,
  // и проверка выдавала бы ложные срабатывания на датах.
  const re = /\d{1,3}(?:[ \s]\d{3})+(?!\d)(?:[.,]\d+)?|\d+(?:[.,]\d+)?/g;
  let m;
  while ((m = re.exec(text)) !== null) {
    const digits = m[0].replace(/[ \s]/g, '').replace(',', '.');
    const val = parseFloat(digits);
    if (!isNaN(val) && digits.replace(/\D/g, '').length >= 2) out.add(val);  // >=2 цифры: отсекаем нумерацию
  }
  return out;
}
const srcNums = numbers(source);
const briefNums = numbers(md);

// Модели разрешено считать простую арифметику из переданных чисел: доли,
// проценты, разницы, отношения. Поэтому кроме «сырых» чисел источника
// собираем множество производных значений (два операнда, 5 операций).
const r2 = x => Math.round(x * 100) / 100;
const srcArr = [...srcNums];
const derived = new Set(), derivedInt = new Set();
for (const a of srcArr) {
  for (const b of srcArr) {
    const vals = [a + b, a - b, a / b, (a - b) / b * 100, a * b];
    for (const x of vals) {
      if (!isFinite(x)) continue;
      derived.add(r2(x));
      derivedInt.add(Math.round(x));
    }
  }
}

const unknown = [];
for (const v of briefNums) {
  const found = srcNums.has(v) ||
                derived.has(r2(v)) || derivedInt.has(Math.round(v)) ||
                srcNums.has(v * 100) || srcNums.has(v / 100) ||   // проценты/доли
                [...srcNums].some(s => Math.abs(s - v) < 0.51);   // округление
  if (!found) unknown.push(v);
}
add('Числа подтверждаются исходными данными', unknown.length === 0,
    unknown.length
      ? 'НЕТ в источниках и не выводятся арифметикой из них: ' +
        unknown.slice(0, 12).join(', ') + (unknown.length > 12 ? ' …' : '') +
        ' — проверить вручную'
      : 'все ' + briefNums.size + ' чисел брифинга подтверждаются данными ' +
        'или выводятся из них простой арифметикой');

// --- 5. Шум не попал в разделы выводов ---
const noiseCats = (pack.noise || []).map(n => n.category);
const outputsOnly = md.split(/##\s*5\./)[0];   // разделы 1–4
const leaked = noiseCats.filter(c => new RegExp(c.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i').test(outputsOnly));
add('Единичные сигналы (шум) не попали в выводы', leaked.length === 0,
    leaked.length ? 'в разделах 1–4 упомянуты шумовые категории: ' + leaked.join(', ')
                  : 'из ' + noiseCats.length + ' шумовых категорий ни одна не попала в разделы выводов');

// --- 6. Гипотезы отделены от выводов ---
const hypMentions = (md.match(/гипотез/gi) || []).length;
add('Гипотезы отделены от подтверждённых выводов', hypMentions >= 2,
    'упоминаний «гипотез» — ' + hypMentions);

// --- 7. Оговорка о недостатке данных, если трендов нет ---
const trendSection = (md.split(/##\s*3\./)[0].split(/##\s*2\./)[1]) || '';
const trendHonest = /недостаточно|нет подтверждённых данных|Данных для корректного вывода/i.test(trendSection);
const trendGrounded = /Основан/i.test(trendSection);
add('Раздел трендов не перегружен выводами без оснований',
    trendHonest || trendGrounded,
    trendHonest ? 'есть явная оговорка о недостатке данных'
                : trendGrounded ? 'каждый тренд приведён со строкой «Основание:»'
                                : 'в разделе трендов нет ни оснований, ни оговорки о нехватке данных');

// --- Итог ---
const passed = checks.filter(c => c.ok).length;
const total = checks.length;

let appendix = '\n\n---\n\n## Приложение. Автоматическая самопроверка качества\n\n';
appendix += 'Проверка выполнена узлом «Самопроверка качества» сразу после генерации брифинга. ';
appendix += 'Пройдено **' + passed + ' из ' + total + '** проверок.\n\n';
appendix += '| № | Проверка | Результат | Детали |\n|---|---|---|---|\n';
checks.forEach((c, i) => {
  appendix += '| ' + (i + 1) + ' | ' + c.name + ' | ' + (c.ok ? '✅ пройдено' : '⚠️ требует внимания') + ' | ' + c.detail + ' |\n';
});
appendix += '\n**Параметры прогона:** тарифных позиций — ' + brief.counts.tariffs +
  ', отзывов — ' + brief.counts.reviews +
  ', сигналов-наблюдений — ' + brief.counts.observations +
  ', гипотез — ' + brief.counts.hypotheses +
  ', исключено единичных сигналов — ' + brief.counts.noise_excluded + '.\n';
appendix += '\n**Служебная информация:** символов в ответе модели — ' + brief.raw_llm_chars +
  ', из них отброшено как служебные рассуждения — ' + brief.reasoning_stripped + '.\n';

return [{
  json: {
    briefing_md: md + appendix,
    generated_at: brief.generated_at,
    run_date: brief.run_date,
    counts: brief.counts,
    self_check: { passed: passed, total: total, checks: checks },
    self_check_passed: passed === total,
    appendix_md: appendix
  }
}];

// ============================================================================
// ШАГ 6. ПОДГОТОВКА БРИФИНГА К ЗАПИСИ НА ДИСК
// ----------------------------------------------------------------------------
// Операция write в узле «Read/Write Files from Disk» работает с БИНАРНЫМИ
// данными, а не с текстовым полем JSON. Поэтому текст брифинга превращается
// в бинарный файл с именем briefing-<дата прогона>.md и MIME-типом text/markdown.
// ============================================================================

const b = $('Самопроверка качества').first().json;
const fileName = 'briefing-' + b.run_date + '.md';

const bin = await helpers.prepareBinaryData(
  Buffer.from(b.briefing_md, 'utf8'),
  fileName,
  'text/markdown'
);

return [{
  json: {
    run_date: b.run_date,
    file_name: fileName,
    briefing_chars: b.briefing_chars,
    self_check_passed: b.self_check_passed,
    briefing_md: b.briefing_md
  },
  binary: { data: bin }
}];

// Финальный узел: возвращает готовый брифинг и результат самопроверки.
// Он же служит ответом при запуске по ссылке (Webhook).
const b = $('Самопроверка качества').first().json;
return [{ json: {
  status: 'ok',
  generated_at: b.generated_at,
  run_date: b.run_date,
  counts: b.counts,
  self_check_passed: b.self_check_passed,
  self_check: b.self_check,
  briefing_md: b.briefing_md
} }];
